window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q08"]=window.__LIBQ["the-gioi-hoan-my"]["q08"]||{};window.__LIBQ["the-gioi-hoan-my"]["q08"]["map"]={"updatedAt":"2026-07-23","count":147,"nodes":[{"id":"cam-dia-trung-tam-chien-truong-mau-mau","name":"Cấm địa trung tâm chiến trường màu máu","cn":"","capDo":"khac","parentId":"binh-nguyen-mau-mau","blurb":"Cấm địa nằm tại trung tâm chiến trường màu máu, phủ đầy bạch cốt, hoa tươi và những xích thần trật tự đứt gãy.","detail":"Bên trong cấm địa có cầu bạch ngọc mở đường, một chiếc kén phát sáng đã vỡ cùng tàn tích lột xác còn mới. Thạch Hạo theo cầu tiến vào và gặp Diệp Khuynh Tiên tại đây.","theLucLienQuan":[],"nguon":["@c0701"]},{"id":"thanh-tri-trung-chuyen-cua-thien-nhan-toc","name":"Thành trì trung chuyển của Thiên Nhân tộc","cn":"","capDo":"thanh","parentId":"thien-chau","blurb":"Một thành trì an toàn của Thiên Nhân tộc tại Thiên châu, nơi Thạch Hạo gặp lại Vân Hi.","detail":"Thành trì có một truyền tống trận cỡ lớn đủ sức đưa người đi xa hàng chục triệu dặm. Đây cũng là nơi Thiên Thần đầu đầy tơ máu mang người trẻ tuổi trọng thương trở về trước khi đoàn người khẩn cấp tiến về tổ địa.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0703"]},{"id":"lanh-dia-thien-nhan-toc","name":"Lãnh địa Thiên Nhân tộc","cn":"","capDo":"vuc","parentId":"thien-chau","blurb":"Lãnh địa rộng lớn do Thiên Nhân tộc kiểm soát tại Thiên châu.","detail":"Khu vực có linh khí nồng đậm, nhiều thành trì lớn và cường giả. Truyền tống trận ở xa không nối thẳng tới tổ địa nhằm tránh tạo đường xâm nhập thuận lợi cho ngoại địch.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0703"]},{"id":"bai-chan-tha-va-duoc-vien-thien-nhan-toc","name":"Bãi chăn thả và dược viên Thiên Nhân tộc","cn":"","capDo":"vuc","parentId":"lanh-dia-thien-nhan-toc","blurb":"Khu chăn thả và trồng dược liệu rộng mười vạn dặm của Thiên Nhân tộc.","detail":"Nơi đây nuôi nhiều linh cầm, dị thú và trồng bảo thụ, thảo dược quý. Toàn khu vực được một đại trận mạnh bảo vệ, từng không bị hủy diệt dù chịu công kích của Chiến đế.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0703"]},{"id":"to-dia-thien-nhan-toc","name":"Tổ địa Thiên Nhân tộc","cn":"","capDo":"vuc","parentId":"lanh-dia-thien-nhan-toc","blurb":"Thần thổ tối cao của Thiên Nhân tộc, nằm sâu trong vùng núi tràn ngập tử khí.","detail":"Tổ địa được bảo vệ bằng nhiều lớp kiểm tra nghiêm mật. Khu vực bên ngoài có núi cao vạn trượng, thác nước, tiên vụ, dị thú và nhiều bảo dược.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0703"]},{"id":"thien-chi-thanh","name":"Thiên Chi Thành","cn":"","capDo":"thanh","parentId":"to-dia-thien-nhan-toc","blurb":"Cổ thành khổng lồ được tử khí từ các dãy núi nâng giữa bầu trời, là tịnh thổ tối cao của Thiên Nhân tộc.","detail":"Thiên Chi Thành là nơi cư trú của những Thiên Nhân mang huyết thống cao quý nhất. Bên trong thành có linh sơn, động phủ, phố xá và thần trì thái cổ dùng để chữa thương.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0703"]},{"id":"san-dien-vo-thien-chi-thanh","name":"Sân diễn võ Thiên Chi Thành","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Khu diễn võ rộng hàng chục dặm trong Thiên Chi Thành, nơi đặt Phi Tiên thạch.","detail":"Sân diễn võ là một khu vực trang nghiêm, rộng hàng chục dặm, có linh khí đậm đặc và đạo tắc khó diễn tả. Hai thiếu nữ hầu cận dẫn Thạch Hạo tới đây để quan sát và tiếp cận Phi Tiên thạch.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0704"]},{"id":"tinh-xa-rung-truc","name":"Tịnh xá trong rừng trúc","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Một tịnh xá nằm trong rừng trúc cạnh hồ nước xanh thẳm tại Thiên Chi Thành.","detail":"Đây là nơi Tê Hà tiếp đón Mạn Châu Sa Hoa và Hoa Sen, đồng thời diễn ra cuộc gặp giữa hai minh châu với Thạch Hạo trước thử thách Phi Tiên thạch.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0705"]},{"id":"ho-nuoc-xanh-tham","name":"Hồ nước xanh thẳm","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Khu vực gần chỗ ở của Thạch Hạo trong Thiên Chi Thành.","detail":"Sau sự kiện Phi Tiên thạch, Thạch Hạo trở về chỗ ở tại khu vực hồ nước xanh thẳm. Mạn Châu Sa Hoa và Hoa Sen được phái tới đây để chăm sóc sinh hoạt cho hắn.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0708"]},{"id":"vuon-linh-duoc-va-khu-nuoi-thu","name":"Vườn linh dược và khu nuôi thú","cn":"","capDo":"khac","parentId":"day-nui-muoi-van-dam","blurb":"Khu vực săn bắn, hái dược và nuôi thú của Thiên Nhân tộc, được mở theo mùa.","detail":"Mạn Châu Sa Hoa và Hoa Sen lấy việc tới khu vực này săn bắn, hái dược làm lý do đưa Thạch Hạo rời Thiên Chi Thành và tiếp cận vực sâu có đầu mối không gian.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0708"]},{"id":"vuc-sau-co-dau-moi-khong-gian","name":"Vực sâu có đầu mối không gian","cn":"","capDo":"khac","parentId":"day-nui-muoi-van-dam","blurb":"Vực sâu nguy hiểm chứa vết nứt không gian, được cho là thông tới một tàn tích thuộc kỷ nguyên Tiên cổ.","detail":"Vực sâu nằm trong dãy núi phía trước Thiên Chi Thành và là nơi từng phát hiện Phi Tiên thạch. Thạch Hạo định dùng đầu mối không gian tại đây để trốn khỏi thành, nhưng bị Thích Thác dùng pháp liên kéo trở lại.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0708"]},{"id":"tan-tich-ky-nguyen-tien-co","name":"Tàn tích kỷ nguyên Tiên cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Di tích hùng vĩ chưa rõ tên, được cho là nằm ở đầu kia của đầu mối không gian dưới vực sâu.","detail":"Tàn tích thuộc kỷ nguyên Tiên cổ được nhắc tới như đích đến có thể có của vết nứt không gian. Phi Tiên thạch từng được tìm thấy từ khu vực liên quan tới đầu mối này.","theLucLienQuan":[],"nguon":["@c0708"]},{"id":"day-nui-muoi-van-dam","name":"Dãy núi mười vạn dặm","cn":"","capDo":"vuc","parentId":"lanh-dia-thien-nhan-toc","blurb":"Dãy núi rộng lớn phía trước Thiên Chi Thành, nơi con em Thiên Nhân tộc săn bắn và hái dược.","detail":"Khu vực này bao gồm vườn linh dược, khu nuôi thú và vực sâu có vết nứt không gian được cho là thông tới tàn tích Tiên cổ.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0708"]},{"id":"cam-khu-thuoc-khu-vuc-khong-nguoi","name":"Cấm khu thuộc khu vực không người","cn":"","capDo":"vuc","parentId":null,"blurb":"Cấm khu mênh mông nằm sâu trong khu vực không người, từng là đích đến của sáu đại Thiên Nhân.","detail":"Sáu đại Thiên Nhân từng mang Tiên Linh Lung tiến vào nơi này để tìm vật chất bất tử. Năm người không trở về, còn người sống sót duy nhất không tiết lộ tai họa đã xảy ra trong Cấm khu.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0709"]},{"id":"cung-dien-co-cua-thien-nhan-toc","name":"Cung điện cổ của Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Nơi các Thiên Thần Thiên Nhân tộc xử lý những sự kiện quan trọng.","detail":"Tại đây, các Thiên Thần nghe báo cáo điều tra về cái chết của Chiến vương trẻ tuổi, nhận ra Ma Hi có thể là Hoang và triệu Thạch Hạo tới xác nhận thân phận.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0710"]},{"id":"thanh-dia-quyet-sach-thien-nhan-toc","name":"Thánh địa quyết sách Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Cung điện phủ sương mù, nơi cao tầng Thiên Nhân tộc xử lý những quyết định trọng yếu.","detail":"Các Thiên Thần thẩm vấn Thạch Hạo tại đây, bác bỏ lai lịch Cấm khu do hắn dựng nên và bí mật bàn cách giữ lại hắn cùng những truyền thừa đang nắm giữ.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0711"]},{"id":"khu-vuc-ben-ngoai-thien-nhan-toc","name":"Khu vực bên ngoài Thiên Nhân tộc","cn":"","capDo":"vuc","parentId":"lanh-dia-thien-nhan-toc","blurb":"Vùng ngoài lãnh địa Thiên Nhân tộc, nơi nhiều lực lượng có Thiên Thần lần lượt xuất hiện.","detail":"Cường giả Chiến tộc, cốt thuyền của đại giáo và chiến thuyền cấp Thiên Thần cùng tiến đến khu vực này vì Hoang và tiên kinh Lôi Đế.","theLucLienQuan":["Thiên Nhân tộc","Chiến tộc"],"nguon":["@c0711"]},{"id":"nha-giam-duoi-long-dat-thien-nhan-toc","name":"Nhà giam dưới lòng đất Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"cung-dien-co-cua-thien-nhan-toc","blurb":"Nhà giam trọng phạm nằm dưới cung điện của Thiên Nhân tộc. Nơi đây chỉ giam những cường giả từ Chân Thần trở lên.","detail":"Nhà giam được phong tỏa cực kỳ kiên cố, tù nhân yếu nhất cũng đạt Chân Thần cảnh, bên trong còn có chuẩn Thiên Thần và nhiều Thiên Thần. Thạch Hạo bị áp giải xuống đây sau khi từ chối giao Lôi Đế pháp và Côn Bằng thuật, rồi kích động các trọng phạm gây bạo động.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0713"]},{"id":"cung-dien-tiep-khach-thien-nhan-toc","name":"Cung điện tiếp khách của Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"thien-chi-thanh","blurb":"Cung điện nơi thần chủ Khổng Tước hội đàm với các Thiên Thần của Thiên Nhân tộc.","detail":"Thạch Hạo được đưa từ địa lao tới đây trong tình trạng trọng thương. Khổng Cầu Kỳ công khai xác nhận hắn là huynh đệ ở hạ giới và trực diện chất vấn các cường giả Thiên Nhân tộc về việc tra tấn ân nhân của Vân Hi.","theLucLienQuan":["Thiên Nhân tộc","Khổng Tước tộc"],"nguon":["@c0714"]},{"id":"canh-cua-nguyen-thuy","name":"Cánh cửa Nguyên thủy","cn":"","capDo":"khac","parentId":null,"blurb":"Cánh cửa bí ẩn mà Liễu Thần đã tiến vào trước khi mất tung tích.","detail":"Phần lớn sinh linh thượng giới cho rằng việc Liễu Thần tiến vào cánh cửa này đồng nghĩa với cái chết. Thần chủ Khổng Tước lại tin Liễu Thần chưa chắc đã chết và có thể tái hiện trên thế gian.","theLucLienQuan":[],"nguon":["@c0715"]},{"id":"tu-vi-chau","name":"Tử Vi châu","cn":"","capDo":"chau","parentId":"ba-ngan-chau","blurb":"Đích đến ban đầu được Lão Thiên Nhân đặt cho cuộc truyền tống Thạch Hạo rời Thiên Chi Thành.","detail":"Tử Vi châu nằm cách Thiên Chi Thành hàng chục châu. Thạch Hạo không chắc đến được nơi này vì Phá giới phù đã bẻ cong thông đạo và liên tục thay đổi tọa độ.","theLucLienQuan":[],"nguon":["@c0719"]},{"id":"duong-ham-hu-khong","name":"Đường hầm hư không","cn":"","capDo":"khac","parentId":null,"blurb":"Thông đạo truyền tống nơi Thạch Hạo bị nhiều Giáo chủ và cường giả truy bắt sau khi rời Thiên Chi Thành.","detail":"Các linh thân của Chủ Ma Quỳ viên, Phó giáo chủ Thiên quốc và Minh chủ xâm nhập đường hầm để bắt giết Thạch Hạo. Phá giới phù sau đó xé mở không gian khác, vặn vẹo thông đạo và đưa hắn thoát đi.","theLucLienQuan":["Thiên Nhân tộc","Thiên quốc","Minh giới","Ma Quỳ viên"],"nguon":["@c0719"]},{"id":"hoa-chau","name":"Hỏa châu","cn":"","capDo":"chau","parentId":null,"blurb":"Châu vực hỗn loạn mà Thạch Hạo đặt chân tới sau khi thoát khỏi Thiên Nhân tộc.","detail":"Hỏa châu tiếp giáp Thiên Tiên châu và Côn châu, cách Thiên Châu ít nhất hàng chục đến gần trăm châu. Nơi đây có giặc cỏ, trộm cướp, nhiều thần quáng và thần liệu quý, quân trú đóng của các thế lực lớn cùng truyền thuyết về tiên kim và Hỗn độn diễm. Đây cũng là địa bàn của người mạo hiểm, nơi thí luyện của các học viện và chiến trường của thiên tài các đại tộc.","theLucLienQuan":["Huyết sư đoàn","Hắc Lang tộc"],"nguon":["@c0720"]},{"id":"dai-thao-nguyen-hoa-chau","name":"Đại thảo nguyên Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Vùng đồng cỏ hoang vu và rộng lớn nơi Thạch Hạo xuất hiện sau khi rời khỏi hư không.","detail":"Đại thảo nguyên là chiến trường của hàng nghìn kỵ sĩ Hắc Lang tộc và Huyết sư đoàn. Cuộc chém giết tại đây có cả cao thủ Thần Hỏa cảnh và hai Chân Thần tham chiến.","theLucLienQuan":["Huyết sư đoàn","Hắc Lang tộc"],"nguon":["@c0720"]},{"id":"phu-phong-thanh","name":"Phù Phong thành","cn":"","capDo":"thanh","parentId":"hoa-chau","blurb":"Thành trì kim loại màu đen có khắc trận pháp tại Hỏa châu. Bên trong thành gần như không có trật tự, các vụ giết người, lừa đảo và trộm cắp diễn ra công khai.","detail":"Thạch Hạo tới Phù Phong thành để tìm nơi có dân cư trong lúc mang thương tích. Ngay khi vào thành, hắn chứng kiến nhiều cuộc chém giết không người can thiệp, trò lừa bán thánh dược giả và một cao thủ Thần Hỏa hành nghề trộm cắp.","theLucLienQuan":["Thư viện Thần Nhai","Kim dược đường"],"nguon":["@c0721"]},{"id":"muoi-van-vach-da-co","name":"Mười vạn vách đá cổ","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Khu vực truyền thừa thuộc thư viện Thần Nhai tại Hỏa châu. Nơi đây được truyền rằng từng có động phủ ngộ đạo của Chân Tiên thời cổ.","detail":"Mười vạn vách đá cổ là một phần nền tảng của thư viện Thần Nhai và góp phần thể hiện bề dày truyền thừa của đạo thống này.","theLucLienQuan":["Thư viện Thần Nhai"],"nguon":["@c0721"]},{"id":"ao-huyet-long","name":"Ao huyết long","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Một địa điểm thuộc thư viện Thần Nhai, có khả năng thai nghén Xích Long câu. Mỗi đời chỉ có thể sinh ra vài con tọa kỵ mang huyết mạch Chân Long này.","detail":"Ao huyết long là nguồn cung Xích Long câu hiếm có của thư viện Thần Nhai, khiến loại tọa kỵ này trở thành dấu hiệu nhận diện những nhân vật quan trọng của đạo thống.","theLucLienQuan":["Thư viện Thần Nhai"],"nguon":["@c0721"]},{"id":"ho-xich-long","name":"Hồ Xích Long","cn":"","capDo":"khac","parentId":"muoi-van-vach-da-co","blurb":"Hồ nước thuộc khu vực Thư viện Thần Nhai, được cho là nơi thai nghén Chân Long xích huyết.","detail":"Những người xuất sắc nhất của Thư viện Thần Nhai được ngâm mình trong hồ để gột rửa và thu được một phần năng lực cùng biến hóa của Xích Long.","theLucLienQuan":["Thư viện Thần Nhai"],"nguon":["@c0722"]},{"id":"di-tich-tien-co","name":"Di tích Tiên cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Di tích liên quan đến kỷ nguyên Tiên cổ, nơi thiên tài ba ngàn châu sẽ tiến hành cuộc tranh tài lớn.","detail":"Người tham gia không được vượt Tôn giả cảnh trước khi tiến vào, nhưng có thể đột phá sau khi đã vào trong. Các đạo thống vì thế để sơ đại áp chế cảnh giới và chuẩn bị bảo hỏa cùng tài nguyên cho chiến trường.","theLucLienQuan":[],"nguon":["@c0722"]},{"id":"con-chau","name":"Côn châu","cn":"","capDo":"chau","parentId":null,"blurb":"Châu vực giáp Phù Phong thành.","detail":"Danh tiếng Thanh Y tại học viện Thiên Tiên đã truyền tới Côn châu.","theLucLienQuan":[],"nguon":["@c0722"]},{"id":"ngoi-lang-co-hang-rao-tai-hoa-chau","name":"Ngôi làng có hàng rào tại Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Ngôi làng có vài trăm gia đình tại Hỏa châu, được bao quanh bởi hàng rào và cảnh giác với người ngoài.","detail":"Thạch Hạo dùng một khối thần liệu đổi lấy quyền lưu trú tại đây, rồi ở trong phòng năm ngày để chữa khỏi thương thế.","theLucLienQuan":[],"nguon":["@c0723"]},{"id":"vuc-sau-hon-van-dam","name":"Vực sâu hơn vạn dặm","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Khe nứt khổng lồ rộng hơn vạn dặm và sâu hơn trăm dặm tại Hỏa châu.","detail":"Vách vực có dấu vết từng bị lửa nung chảy. Dưới đáy là phế tích mới trồi lên từ sâu trong lòng đất, khí hỗn độn, thành cổ sụp đổ và đạo đài đặt quan tài đồng.","theLucLienQuan":[],"nguon":["@c0723"]},{"id":"thanh-co-duoi-long-dat","name":"Thành cổ dưới lòng đất","cn":"","capDo":"thanh","parentId":"vuc-sau-hon-van-dam","blurb":"Quần thể cung điện cổ hùng vĩ đã sụp đổ, được phát hiện dưới đáy vực sâu tại Hỏa châu.","detail":"Thành cổ còn lưu lại những phù văn rách nát phát sáng. Bên trong có đạo đài lớn như núi, chín bộ xương khổng lồ giống Chân Long và hai lớp quan tài đồng phát ra khí hỗn độn.","theLucLienQuan":[],"nguon":["@c0723"]},{"id":"dao-dai-trong-thanh-co","name":"Đạo đài trong thành cổ","cn":"","capDo":"khac","parentId":"thanh-co-duoi-long-dat","blurb":"Đạo đài lớn tựa núi nằm trong thành cổ dưới lòng đất.","detail":"Trên đạo đài có chín bộ xương khổng lồ phát ra khí tức bất hủ và phủ đầy phù văn. Phía sau các bộ xương là quan tài đồng lớn chứa một quan tài đồng nhỏ phát ra khí hỗn độn.","theLucLienQuan":[],"nguon":["@c0723"]},{"id":"khong-gian-kin-sau-duoi-long-dat","name":"Không gian kín sâu dưới lòng đất","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian bí mật nằm cách cổ thành hàng trăm nghìn dặm dưới lòng đất.","detail":"Thạch Hạo dùng Phá không phù đưa quan tài đồng, chín bộ khung xương và bảo hỏa phù văn tới đây nhằm tránh bị người ngoài phát hiện.","theLucLienQuan":[],"nguon":["@c0725"]},{"id":"hoc-vien-thien-tien","name":"Học viện Thiên tiên","cn":"","capDo":"khac","parentId":"thien-tien-chau","blurb":"Thánh địa tu đạo náo nhiệt tại Thiên Tiên châu, gần vùng giao giới ba châu.","detail":"Học viện nằm cách Phù Phong thành khoảng một ngày bay của Thạch Hạo. Đây là nơi Nguyệt Thiền thứ thân và Phượng Vũ đang ở.","theLucLienQuan":["Học viện Thiên tiên"],"nguon":["@c0725","@c0747"],"aliases":["Thư viện Thiên Tiên"]},{"id":"cac-thanh-ve-tinh-thu-vien-thien-tien","name":"Các thành vệ tinh Thư viện Thiên Tiên","cn":"","capDo":"thanh","parentId":"hoc-vien-thien-tien","blurb":"Hơn mười khu thành không có tường bao quanh Thư viện Thiên Tiên.","detail":"Các thành vệ tinh hợp cùng phố chợ thành một vùng rộng hơn cả nội viện, có tới hàng triệu người thường trú hoặc tạm trú.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0726"]},{"id":"khu-cho-ngoai-thu-vien-thien-tien","name":"Khu chợ ngoài Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu giao dịch quy mô lớn nằm ở vùng ngoại vi Thư viện Thiên Tiên.","detail":"Nơi đây rao bán bảo dược, bí bảo, cốt thư và nhiều thần thông hiếm. Hàng thật, hàng kém chất lượng, hàng giả và hàng nhái cùng tồn tại trong các quầy hàng và phòng đấu giá.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0726"]},{"id":"co-mon-thu-vien-thien-tien","name":"Cổ môn Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Cánh cửa cổ dẫn vào Thư viện Thiên Tiên, tồn tại từ thời thái cổ.","detail":"Cổ môn được dựng bằng mười hai trụ đá lớn, trên đó chạm khắc hình thụy thú và chim thần.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0726"]},{"id":"di-tich-tien-hien","name":"Di tích tiên hiền","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu truyền thừa sâu trong thư viện, lưu giữ dấu tích của các cường giả tiền nhân.","detail":"Nơi đây có di khắc Chân Tiên, cảm ngộ Giáo chủ và bia đá ghi tâm đắc của Đế tộc. Việc có người tiến vào đã làm xuất hiện bóng người khổng lồ giảng đạo cùng mưa ánh sáng thanh lọc thân thể và linh hồn của người bên ngoài.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0726"]},{"id":"tien-tri-thu-vien-thien-tien","name":"Tiên trì Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Nơi gột rửa dành cho các đệ tử siêu tuyệt của Thư viện Thiên Tiên.","detail":"Tiên trì là địa điểm tu hành được cấp cho người vượt qua thang trời, đồng thời thường có các nữ học viên nổi danh trên bảng tuyệt sắc lui tới.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0726"]},{"id":"thang-troi","name":"Thang trời","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu thử thách nằm bên trong cửa lớn Thư viện Thiên Tiên, đã phủ bụi vì lâu năm không có người khiêu chiến.","detail":"Thang trời gồm nhiều cửa kiểm nghiệm. Mỗi khi người khiêu chiến vượt qua một cửa, tiếng chuông sẽ vang khắp Thư viện Thiên Tiên và truyền tới khu phố chợ bên ngoài.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0727"]},{"id":"dai-cao-thang-troi","name":"Đài cao thang trời","cn":"","capDo":"khac","parentId":"thang-troi","blurb":"Đài đá rộng lớn đối diện cửa Thư viện Thiên Tiên, là nơi bắt đầu thử thách thang trời.","detail":"Sau khi lớp bụi được pháp lực thổi sạch, bệ đá cùng những hoa văn thần bí phức tạp hiện ra. Khi Thạch Hạo bước lên, nơi này biến thành một góc đấu trường.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0727"]},{"id":"dau-truong-ban-huyet-canh","name":"Đấu trường Bàn Huyết cảnh","cn":"","capDo":"khac","parentId":"thang-troi","blurb":"Cửa đầu của thang trời dùng để kiểm nghiệm thành tựu tại Bàn Huyết cảnh.","detail":"Đấu trường khiến người khiêu chiến trở về hình thái trẻ nhỏ và phát ra gợn sóng để người quan sát cảm nhận trạng thái Bàn Huyết cảnh. Thạch Hạo vượt cửa bằng cách nâng tảng đá khoảng mười lăm đến mười sáu vạn cân rồi đá nó nổ tung.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0727"]},{"id":"cua-lon-thu-vien-thien-tien","name":"Cửa lớn Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu cửa chính của Thư viện Thiên Tiên, nơi đám đông tụ tập sau khi Thạch Hạo vượt qua thang trời.","detail":"Khu vực có môn khuyết được mười hai trụ đá trắng nâng đỡ. Tin có người vượt ải khiến nơi đây trở nên náo động.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0729"]},{"id":"than-lien-do-kiep-tri","name":"Thần liên độ kiếp trì","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Một tiên trì của Thư viện Thiên Tiên có Thần liên độ kiếp sinh trưởng.","detail":"Các nữ tử trên bảng tuyệt sắc được sắp thứ tự để tiến vào tiên trì. Ông lão mặc đạo bào vàng hứa Thạch Hạo sẽ có nhiều cơ hội vào đây sau khi gia nhập đạo trường.","theLucLienQuan":["Thư viện Thiên Tiên","Đạo Tràng Chí Tôn"],"nguon":["@c0729"]},{"id":"dai-dien-thien-tien","name":"Đại điện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Đại điện nơi các cường giả của Thư viện Thiên Tiên tiếp nhận tin tức quan trọng.","detail":"Hai vị Thiên Thần đến đây báo cáo rằng người vượt Thiên quan không gia nhập thư viện và nêu nghi vấn một nhân vật từng rời đi đã trở về.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0729"]},{"id":"dao-trang-chi-ton-dia-danh","name":"Đạo Tràng Chí Tôn","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu đạo trường cổ xưa nằm gần nơi sâu nhất của Thư viện Thiên Tiên.","detail":"Lối vào là một môn khuyết cổ xưa chọc vào mây, treo tấm biển mang bốn chữ Đạo Tràng Chí Tôn. Ông lão mặc đạo bào vàng đưa Thạch Hạo tới đây và xác nhận hắn đã trở thành đệ tử của đạo trường.","theLucLienQuan":["Đạo Tràng Chí Tôn","Thư viện Thiên Tiên"],"nguon":["@c0729"]},{"id":"son-mon-dao-trang-chi-ton","name":"Sơn môn Đạo tràng Chí Tôn","cn":"","capDo":"khac","parentId":"dao-trang-chi-ton-dia-danh","blurb":"Lối vào và khu sơn môn của Đạo tràng Chí Tôn, ban đầu hiện ra dưới hình thức một môn khuyết hùng vĩ.","detail":"Sau khi đưa Thạch Hạo trở lại, Tề Đạo Lâm ấn tay khiến ngọn núi phát sáng và làm hiện ra một cung điện lớn như thiên cung. Môn khuyết chỉ là lối vào, không đại diện cho toàn bộ phạm vi mà Tề Đạo Lâm xem là đạo trường.","theLucLienQuan":["Đạo tràng Chí Tôn"],"nguon":["@c0730"]},{"id":"son-mon-cua-te-dao-lam","name":"Sơn môn của Tề Đạo Lâm","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Sơn môn nơi Tề Đạo Lâm từng đón Thạch Hạo và dựng nên cảnh tượng nguy nga. Sau khi hai người rời đi, nơi này hiện nguyên trạng là môn khuyết cùng cung điện đổ nát.","detail":"Khi người của Học viện Thiên Tiên tới nơi, môn khuyết nguy nga đã trở thành kiến trúc rách nát gần sụp đổ. Cung điện lớn trên núi cũng biến lại thành phế tích ngập cỏ dại.","theLucLienQuan":["Đạo thống của Tề Đạo Lâm","Học viện Thiên Tiên"],"nguon":["@c0731"]},{"id":"vung-hoang-mac","name":"Vùng hoang mạc","cn":"","capDo":"khac","parentId":"thuong-gioi","blurb":"Hoang mạc nơi Tề Đạo Lâm bắt đầu truyền Bát Cửu Thiên Công cho Thạch Hạo. Đây cũng là địa điểm Thạch Hạo thực hiện bài khổ luyện gánh núi chạy đường dài.","detail":"Tại vùng hoang mạc, Tề Đạo Lâm giải thích bản chất pháp môn mới và buộc Thạch Hạo mỗi ngày gánh núi chạy hơn mấy vạn dặm để bước đầu hợp nhất thân thể, pháp thuật và tinh thần.","theLucLienQuan":["Đạo thống của Tề Đạo Lâm"],"nguon":["@c0731"]},{"id":"thao-nguyen-bien-gioi-hoa-chau-thien-tien-chau","name":"Thảo nguyên biên giới Hỏa châu – Thiên Tiên châu","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng thảo nguyên nằm gần Học viện Thiên Tiên, giữa Hỏa châu và Thiên Tiên châu.","detail":"Những người tìm kiếm thần quáng tại đây phát hiện ngọn núi do Thạch Hạo gánh và hiểu lầm đó là Sơn thần hoặc sơn bảo thông linh, dẫn đến một cuộc truy đuổi.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0732"]},{"id":"than-tri-cua-hoc-vien-thien-tien","name":"Thần trì của Học viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Thần trì nằm trong Học viện Thiên Tiên và là nơi Thạch Hạo muốn tới để tìm Thần liên độ kiếp.","detail":"Tề Đạo Lâm trao cho Thạch Hạo một lệnh bài kim loại màu đen, nhờ đó hắn có thể đi thẳng tới thần trì mà không bị ngăn cản.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0733"]},{"id":"cong-hoc-vien-thien-tien","name":"Cổng Học viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu vực trước cổng Học viện Thiên Tiên là nơi Thạch Hạo dựng bảng nhận nhiệm vụ đánh thuê.","detail":"Thạch Hạo công khai thu phí để đánh học viên lớp dưới hoặc các sư huynh lâu năm, gây chấn động trong học viện và khiến Tề Đạo Lâm phải gọi hắn trở về.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0733"]},{"id":"dao-truong-chi-ton","name":"Đạo trường Chí tôn","cn":"","capDo":"khac","parentId":"son-mon-cua-te-dao-lam","blurb":"Đạo trường Chí tôn là sơn môn suy tàn do Tề Đạo Lâm làm đạo chủ và Thạch Hạo nhận thân phận Đại sư huynh.","detail":"Phần lớn kiến trúc tại đây đã trở thành phế tích sau khi các đại giáo hợp sức phá hủy những công trình mà Tề Đạo Lâm từng mang về. Đây cũng là nơi Thạch Hạo trấn áp nhóm học viên Học viện Thiên Tiên đến gây sự.","theLucLienQuan":["Đạo trường Chí tôn"],"nguon":["@c0733"]},{"id":"khu-vuc-sau-nhat-cua-hoc-vien-thien-tien","name":"Khu vực sâu nhất của Học viện Thiên Tiên","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Bảo địa nằm sâu trong Học viện Thiên Tiên, có khí lành và ánh sáng rực rỡ.","detail":"Muốn tiến vào khu vực này phải vượt qua nhiều vùng núi cùng hàng chục lớp trận pháp. Tiên trì trồng Thần liên độ kiếp nằm tại vùng sâu bên trong.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0734"]},{"id":"tieu-thien-the-gioi-giua-ho","name":"Tiểu thiên thế giới giữa hồ","cn":"","capDo":"gioi-nho","parentId":"than-tri-cua-hoc-vien-thien-tien","blurb":"Một không gian đặc thù nằm trong vùng sâu của tiên trì Học viện Thiên Tiên.","detail":"Đại trận và cốt văn dày đặc khiến nơi đây tràn ngập thần quang cùng lôi điện. Linh thức và trùng đồng đều bị áp chế, khó phát huy tác dụng dò xét.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0735"]},{"id":"noi-ho-duoi-than-lien-do-kiep","name":"Nội hồ dưới Thần liên độ kiếp","cn":"","capDo":"khac","parentId":"tieu-thien-the-gioi-giua-ho","blurb":"Hồ nhỏ nằm trong tiên trì lớn, là nơi Thần liên độ kiếp cắm rễ.","detail":"Nội hồ chứa chất lỏng vàng phát sáng như dung nham và được cốt văn phong tỏa nghiêm ngặt. Thạch Hạo không thể tiến vào nên chỉ thu lấy thần dịch chảy ra khu vực bên ngoài.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0735"]},{"id":"cam-dia-nui-bang","name":"Cấm địa núi băng","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Những vùng băng tuyết cấm kỵ nơi một số chí tôn trẻ tuổi cổ đại tự phong để chờ đại chiến ba ngàn châu thích hợp.","detail":"Một số thiên kiêu từng đứng đầu các thời đại trước đã tự phong dưới núi băng và trong các cấm địa băng tuyết, chờ cơ hội tranh đoạt tạo hóa lớn từ kỷ nguyên Tiên cổ.","theLucLienQuan":[],"nguon":["@c0740"]},{"id":"hang-tuyet-co-dai","name":"Hang tuyết cổ đại","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Một trong những nơi các sinh linh trẻ tuổi từng xưng hùng ở những thời đại khác nhau tự phong và ngủ đông.","detail":"Các hang tuyết cổ đại là nơi mai táng và tự phong của một số chí tôn trẻ tuổi cổ đại đang chờ kỳ đại chiến ba ngàn châu thích hợp để xuất thế.","theLucLienQuan":[],"nguon":["@c0740"]},{"id":"tien-co","name":"Tiên cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Một kỷ nguyên cổ xưa đã bị chôn vùi hoàn toàn, gắn với nguồn gốc của Tam thế đồng quan và những tạo hóa lớn.","detail":"Theo Tề Đạo Lâm, Tam thế đồng quan bắt nguồn từ Tiên cổ và là vật duy nhất cùng chín con rồng rời đi sau khi kỷ nguyên này bị chôn vùi. Tạo hóa từ Tiên cổ cũng là mục tiêu khiến nhiều quán quân cổ đại tự phong qua năm tháng để tiếp tục tham dự đại chiến ba ngàn châu.","theLucLienQuan":[],"nguon":["@c0740"]},{"id":"tien-tho-cua-dai-quyet-chien-ba-ngan-chau","name":"Tiên thổ của đại quyết chiến ba ngàn châu","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Chiến trường của đại quyết chiến ba ngàn châu, có cánh cửa thần giới hạn cảnh giới của người tiến vào.","detail":"Cánh cửa thần ngăn người có tu vi vượt quá Tôn giả cảnh bước vào tiên thổ. Sau khi vượt qua cửa, người dự tuyển có thể đột phá mà không còn chịu giới hạn cảnh giới ban đầu.","theLucLienQuan":[],"nguon":["@c0741"]},{"id":"phe-tich-tien-co-duoi-hoa-chau","name":"Phế tích Tiên cổ dưới Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Di tích Tiên cổ nằm sâu dưới lòng đất Hỏa châu, nơi Thạch Hạo và Nguyệt Thiền tìm thấy Thanh Nguyệt diễm.","detail":"Phế tích nằm sau những khe đất dưới đáy một hẻm núi hoang vu. Phù văn còn sót lại chiếu sáng thế giới ngầm, nơi Thanh Nguyệt diễm hiện ra dưới hình thái một vầng trăng xanh.","theLucLienQuan":[],"nguon":["@c0742"]},{"id":"khu-tinh-tho-nu-sinh","name":"Khu tịnh thổ nữ sinh","cn":"","capDo":"khac","parentId":"hoc-vien-thien-tien","blurb":"Khu cư trú dành cho nữ sinh trong Học viện Thiên Tiên, được trận pháp bảo vệ.","detail":"Khu vực có hồ xanh, cổ thụ phát sáng và những dãy tịnh xá nằm trên vách núi cùng rừng tùng. Lệnh bài đặc biệt của học viện có thể cho phép người mang vượt qua trận pháp bảo vệ.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0742"]},{"id":"linh-son-cua-nguyet-thien","name":"Linh sơn của Nguyệt Thiền","cn":"","capDo":"khac","parentId":"khu-tinh-tho-nu-sinh","blurb":"Nơi ở yên tĩnh của Nguyệt Thiền trong khu nữ sinh Học viện Thiên Tiên.","detail":"Linh sơn được khí lành bao phủ. Thạch Hạo tới đây hội ngộ Nguyệt Thiền trước khi hai người cùng lên đường tìm Thanh Nguyệt diễm.","theLucLienQuan":["Học viện Thiên Tiên"],"nguon":["@c0742"]},{"id":"tien-quang-bay-mau","name":"Tiên quáng bảy màu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Quáng động nguy hiểm tại Hỏa châu, được cho là nơi sản sinh tiên kim bảy màu.","detail":"Chưa ai khai thác thành công thần liệu trong tiên quáng. Một số người đứng đầu đại giáo từng thâm nhập rồi bỏ mạng, khiến nơi này trở thành khu vực đặc biệt nguy hiểm.","theLucLienQuan":["Các đại giáo thượng giới"],"nguon":["@c0742"]},{"id":"hem-nui-hoang-vu","name":"Hẻm núi hoang vu","cn":"","capDo":"khac","parentId":"dai-thao-nguyen-hoa-chau","blurb":"Hẻm núi sâu và rộng trên đại thảo nguyên Hỏa châu, ít sinh linh sinh sống.","detail":"Hẻm núi rộng tới hàng vạn dặm và không có thần quáng nổi tiếng. Từ đáy vực, Thạch Hạo và Nguyệt Thiền xuyên qua các khe đất để tiến vào phế tích Tiên cổ nằm sâu dưới lòng đất.","theLucLienQuan":[],"nguon":["@c0742"]},{"id":"phe-tich","name":"Phế tích","cn":"","capDo":"khac","parentId":null,"blurb":"Phế tích nơi Nguyệt Thiền hoàn tất việc thu phục Thanh Nguyệt diễm.","detail":"Tại phế tích này, Nguyệt Thiền hoàn thành khế ước với cổ hỏa, để ngọn lửa hóa thành bảo y rồi dung hợp với dấu ấn cô gái tại mi tâm.","theLucLienQuan":[],"nguon":["@c0745"]},{"id":"quang-mo-thien-nhan-toc-hoa-chau","name":"Quặng mỏ của Thiên Nhân tộc tại Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Một cứ điểm bên ngoài của Thiên Nhân tộc nằm tại Hỏa châu.","detail":"Thạch Hạo nêu quặng mỏ này làm mục tiêu cụ thể trong kế hoạch đánh phá những đạo tràng và cơ sở bên ngoài của Thiên Nhân tộc. Tề Đạo Lâm đã cho phép hắn lên đường.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0748"]},{"id":"mo-quang-co-cua-thien-nhan-toc","name":"Mỏ quặng cổ của Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"hai-khu-mo-cua-thien-nhan-toc","blurb":"Mỏ cổ nằm dưới chân một ngọn núi tại Hỏa châu và được nhiều Chân Thần canh giữ.","detail":"Sâu trong mỏ có một tảng đá dài khoảng bốn trượng, tỏa sương như tiên khí và chứa tạo hóa chưa rõ. Ít nhất mười Chân Thần được bố trí quanh khu vực trước khi Thạch Hạo lẻn xuống lòng đất.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0749"]},{"id":"hai-khu-mo-cua-thien-nhan-toc","name":"Hai khu mỏ của Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Hai khu mỏ nổi tiếng của Thiên Nhân tộc nằm gần Thiên Tiên châu.","detail":"Hai khu mỏ có diện tích lớn, giàu vật liệu quý hiếm và đã được khai thác nhiều năm nhưng thần liệu vẫn chưa cạn. Một trong hai nơi chứa mỏ cổ được bảo vệ đặc biệt nghiêm ngặt.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0749"]},{"id":"dong-co-phia-tren-mo-quang-co","name":"Đồng cỏ phía trên mỏ quặng cổ","cn":"","capDo":"khac","parentId":"mo-quang-co-cua-thien-nhan-toc","blurb":"Khu đồng cỏ phía trên mỏ quặng cổ, nơi cuộc truy sát tiếp tục sau khi Thạch Hạo phá mặt đất thoát ra.","detail":"Tại đây, các Chân Thần tiếp tục dùng pháp khí truy chém Thạch Hạo. Tảng đá kỳ lạ cũng hoàn toàn nứt vỡ trên khu vực này, giải phóng khí tức đại Đạo và để lộ kỳ vật bên trong.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0750"]},{"id":"toi-chau","name":"Tội châu","cn":"","aliases":[],"capDo":"chau","parentId":null,"blurb":"Một châu có các đạo thống mang nguồn gốc hạ giới.","detail":"Các đạo thống tại Tội châu bị hai Thiên Thần Thiên Nhân tộc đe dọa vì bị quy là có liên quan đến vụ tiên chủng biến mất.","theLucLienQuan":["Hỏa tộc","Thiên Nhân tộc"],"nguon":["@c0753"]},{"id":"dao-trang-trong-khu-mo-thien-nhan-toc","name":"Đạo tràng trong khu mỏ Thiên Nhân tộc","cn":"","capDo":"khac","parentId":"dai-thao-nguyen","blurb":"Đạo tràng quản lý các mỏ quặng của Thiên Nhân tộc, có những cung điện xanh vàng và lực lượng Thần Hỏa cảnh trấn thủ.","detail":"Phần lớn Chân Thần tại đây đã theo hai Thiên Thần đi tìm tiên trân thất lạc, khiến lực lượng phòng thủ suy yếu. Thạch Hạo tập kích nơi này, đánh bại bốn thần linh trấn thủ và san bằng toàn bộ cung điện thành phế tích.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0754"]},{"id":"than-quang-de-nhat-cua-thien-nhan-toc","name":"Thần quáng đệ nhất của Thiên Nhân tộc","cn":"","aliases":["Mỏ quặng lớn nhất của Thiên Nhân tộc"],"capDo":"khac","parentId":"dai-thao-nguyen","blurb":"Mỏ quặng lớn nhất của Thiên Nhân tộc, từng là nơi để thất lạc Tiên kim và được ba Chân Thần trấn giữ.","detail":"Thạch Hạo chủ động tới đây đối đầu ba Chân Thần. Nhờ lôi vân tự nhiên bao phủ khu vực, hắn thi triển bảo thuật Lôi Đế dẫn thiên uy và giết chết toàn bộ lực lượng Chân Thần trấn thủ.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0754"]},{"id":"khu-mo-hoa-toc","name":"Khu mỏ Hỏa tộc","cn":"","capDo":"khac","parentId":"dai-thao-nguyen-hoa-chau","blurb":"Khu quặng nằm sâu trong đại thảo nguyên Hỏa châu, nơi Thiên Nhân tộc gây sức ép với Hỏa tộc nhằm truy tìm Hoang.","detail":"Hai Thiên Thần Thiên Nhân tộc dẫn nhiều người và Chân Thần tới đây gây sức ép với Hỏa tộc cùng các đại tộc hạ giới. Khi tin khu mỏ lớn nhất của Thiên Nhân tộc bị Hoang tập kích truyền tới, họ chịu sự chế nhạo của các đạo thống và phải rút đi.","theLucLienQuan":["Hỏa tộc","Thiên Nhân tộc"],"nguon":["@c0755"]},{"id":"thao-nguyen-quanh-than-quang","name":"Thảo nguyên quanh thần quáng","cn":"","aliases":[],"capDo":"khac","parentId":"than-quang-de-nhat-cua-thien-nhan-toc","blurb":"Vùng thảo nguyên rộng lớn bao quanh thần quáng đệ nhất của Thiên Nhân tộc.","detail":"Khu vực này vừa trải qua một trận mưa giông dữ dội, sau đó trở thành nơi lực lượng Thiên Nhân tộc tập kết và phát lệnh truy sát Hoang.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0756"]},{"id":"thao-nguyen-hoa-chau","name":"Thảo nguyên Hỏa châu","cn":"","capDo":"vuc","parentId":"hoa-chau","blurb":"Vùng thảo nguyên rộng lớn tại Hỏa châu, nơi sinh sống của Độc Giác thú và Lang tộc.","detail":"Đây là khu vực thần quáng của Thiên Nhân tộc bị phá hủy thành hồ nước, đồng thời là địa bàn của hai tộc quần đã hỗ trợ truy dấu Thạch Hạo.","theLucLienQuan":["Thiên Nhân tộc","Lang tộc thảo nguyên Hỏa châu","Độc Giác thú thảo nguyên Hỏa châu"],"nguon":["@c0758"]},{"id":"thanh-son-doc-giac","name":"Thánh sơn Độc giác","cn":"","capDo":"khac","parentId":"thao-nguyen-hoa-chau","blurb":"Thánh sơn trên thảo nguyên Hỏa châu, nơi cư trú của Độc Giác thú cấp Thiên Thần.","detail":"Hai đại Thiên Thần của Thiên Nhân tộc tới đây thỉnh cầu Độc Giác thú cấp Thiên Thần hỗ trợ xác định manh mối truy tìm Hoang.","theLucLienQuan":["Độc Giác thú thảo nguyên Hỏa châu","Thiên Nhân tộc"],"nguon":["@c0758"]},{"id":"hang-soi","name":"Hang sói","cn":"","capDo":"khac","parentId":"thao-nguyen-hoa-chau","blurb":"Nơi cư trú của Thiên lang và Lang tộc trên thảo nguyên Hỏa châu.","detail":"Hai đại Thiên Thần của Thiên Nhân tộc tiến vào hang sói để thỉnh cầu Thiên lang cung cấp manh mối về tung tích Hoang.","theLucLienQuan":["Lang tộc thảo nguyên Hỏa châu","Thiên Nhân tộc"],"nguon":["@c0758"]},{"id":"day-nui-dao-trang-chi-ton","name":"Dãy núi Đạo tràng Chí Tôn","cn":"","capDo":"vuc","parentId":"hoa-chau","blurb":"Dãy núi hoang vu nơi sơn môn Đạo tràng Chí Tôn tọa lạc, cũng là khu vực vô số tu sĩ tập trung xem trận quyết chiến.","detail":"Khu vực có cổ mộc, cỏ dại và những ngọn núi tỏa khí lành. Sơn môn cùng cổng chào đã đổ nát, để lại phế tích nơi U Vũ gọi Thạch Hạo ra giao chiến.","theLucLienQuan":["Đạo trường Chí Tôn"],"nguon":["@c0759"]},{"id":"dinh-nui-chien-truong","name":"Đỉnh núi chiến trường","cn":"","capDo":"khac","parentId":"day-nui-dao-trang-chi-ton","blurb":"Đỉnh núi ở cách xa sơn môn Đạo tràng Chí Tôn, được chọn làm nơi diễn ra trận chiến giữa Thạch Hạo và U Vũ.","detail":"Thạch Hạo chủ động dẫn U Vũ tới đỉnh núi này để tránh dư âm chiến đấu phá hủy di tích Đạo tràng Chí Tôn. Tại đây, hai người lần lượt giao đấu bằng thần thông và quyền ấn.","theLucLienQuan":["Đạo trường Chí Tôn","Thiên Nhân tộc"],"nguon":["@c0759"]},{"id":"vung-nui-dien-ra-tran-chien","name":"Vùng núi diễn ra trận chiến","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng núi nơi Thạch Hạo và U Vũ tiến hành cuộc quyết đấu trước sự chứng kiến của tu sĩ nhiều tộc.","detail":"Nơi đây tập trung các cường giả Thiên Nhân tộc cùng nhiều thiên tài quan chiến. Sự phục hồi và lột xác của U Vũ nhờ Thiên Mệnh thạch khiến toàn vùng náo động.","theLucLienQuan":["Thiên Nhân tộc","Thư viện Thiên Tiên"],"nguon":["@c0762"]},{"id":"nha-giam-hu-khong","name":"Nhà giam hư không","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian chiến đấu do Hư không đạo của U Vũ tạo ra để áp chế đối thủ.","detail":"Trong nhà giam hư không, U Vũ có ưu thế như chúa tể và có thể áp chế ánh sáng, âm thanh, thân thể cùng nguyên thần. Thạch Hạo dùng Động thiên duy nhất bảo vệ bản thân, sau đó phá nổ không gian này để trở lại thế giới hiện thực.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0763"]},{"id":"vung-nui-quanh-son-mon-nho","name":"Vùng núi quanh sơn môn nhỏ","cn":"","capDo":"vuc","parentId":"thuong-gioi","blurb":"Chiến trường hiện thực nơi Thạch Hạo quyết đấu U Vũ trước sự chứng kiến của tu sĩ các giáo.","detail":"Quyền kình trong trận chiến khiến núi nổ tung và mặt đất nứt vỡ. Tại đây, Thạch Hạo chém ngang U Vũ, đoạt Thiên Mệnh thạch và bị công khai thân phận Hoang.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0763"]},{"id":"day-nui-ngoai-son-mon","name":"Dãy núi ngoài sơn môn","cn":"","capDo":"khac","parentId":"son-mon-dao-trang-chi-ton","blurb":"Dãy núi bên ngoài sơn môn Đạo tràng Chí Tôn, nơi Mạc La hai lần bị Tề Đạo Lâm đánh văng tới.","detail":"Hơn hai mươi ngọn núi bị đứt đoạn khi Mạc La trúng đòn đầu tiên. Sau đó vị Thiên Thần lại bị sóng âm vàng đánh bay vào dãy núi và nằm trọng thương, rất lâu không thể đứng dậy.","theLucLienQuan":["Đạo tràng Chí Tôn","Thiên Nhân tộc"],"nguon":["@c0766"]},{"id":"giao-gioi-ba-chau","name":"Giao giới ba châu","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực giáp ranh Hỏa châu, Thiên Tiên châu và Côn châu quanh Đạo tràng Chí Tôn.","detail":"Tinh lực của người Hộ đạo làm chấn động khu vực này khi lão khôi phục trạng thái thanh niên và chuẩn bị quyết đấu với Tề Đạo Lâm.","theLucLienQuan":["Đạo tràng Chí Tôn","Thiên Nhân tộc"],"nguon":["@c0767"]},{"id":"tien-dien-bang-dong","name":"Tiên điện bằng đồng","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ điện khổng lồ được khí hỗn độn và mẫu khí thiên địa bao quanh, lưu giữ di khắc cổ đại cùng truyền thừa Nhân Tiên.","detail":"Đây là nơi chủ thân truyền nhân Tiên điện lộ diện, triệu hồi thứ thân trở về và chuẩn bị hợp nhất hai thân trước đại quyết chiến thiên tài ba ngàn châu.","theLucLienQuan":["Tiên điện"],"nguon":["@c0768"]},{"id":"nui-tim-co-hang-co","name":"Núi tím có hang cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng núi tím trường tồn từ xa xưa, bên trong có hang cổ dùng làm nơi bế quan.","detail":"Chàng trai tóc tím có mắt dọc phá quan tại đây sau hai mươi năm bị giấu kín và rèn luyện sinh tử.","theLucLienQuan":[],"nguon":["@c0768"]},{"id":"ho-nuoc-mau-vang","name":"Hồ nước màu vàng","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ nước màu vàng che giấu một thủy phủ tuyệt thế dưới đáy.","detail":"Mặt hồ sôi trào khi thủy phủ phát thần quang và Hỗn độn trận mở ra, báo hiệu thiếu nữ tóc vàng thức tỉnh rồi lao lên trời.","theLucLienQuan":[],"nguon":["@c0768"]},{"id":"cam-dia","name":"Cấm địa","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi một số kỳ tài cổ đại từng bị cho là đã chết vẫn đang ẩn mình.","detail":"Tề Đạo Lâm cho biết một số quái vật cổ đại được ghi nhận là đã thất bại hoặc chết thực ra còn sống trong cấm địa và có thể tham dự cuộc tranh phong đời này.","theLucLienQuan":[],"nguon":["@c0769"]},{"id":"co-dia-chua-tam-the-dong-quan","name":"Cổ địa chứa Tam thế đồng quan","cn":"","capDo":"khac","parentId":null,"blurb":"Một cổ địa chưa được gọi tên cụ thể, nơi Thạch Hạo từng nhìn thấy Tam thế đồng quan.","detail":"Tam thế đồng quan dừng tại đây cùng chín con rồng kéo quan tài. Thạch Hạo tiết lộ địa điểm này cho Tề Đạo Lâm khi kể lại trải nghiệm của mình.","theLucLienQuan":[],"nguon":["@c0769"]},{"id":"hang-ngam-chua-tam-the-dong-quan","name":"Hang ngầm chứa Tam thế đồng quan","cn":"","capDo":"khac","parentId":"thao-nguyen-hoa-chau","blurb":"Hang động nằm sâu dưới thảo nguyên Hỏa châu, được Thạch Hạo dùng làm nơi cất giấu Tam thế đồng quan cùng chín bộ long cốt.","detail":"Thạch Hạo từng đào hang ngầm sâu không rõ bao nhiêu vạn dặm dưới mặt đất. Hắn dẫn Tề Đạo Lâm tới đây bằng pháp môn hành Thổ, sau đó chứng kiến Tam thế đồng quan tự mở và một bóng người bí ẩn xuất hiện.","theLucLienQuan":["Đạo tràng Chí Tôn"],"nguon":["@c0770"]},{"id":"the-gioi-duoi-long-dat-hoa-chau","name":"Thế giới dưới lòng đất Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Không gian dưới lòng đất Hỏa châu, nơi đặt Tam thế đồng quan và đốm lửa thần bí.","detail":"Thạch Hạo và Tề Đạo Lâm thăm dò Tam thế đồng quan tại đây. Sau khi mười bóng sáng rời đi, đốm lửa thần bí phản kích Tề Đạo Lâm rồi ở lại gần Thạch Hạo trong không gian này.","theLucLienQuan":["Chí Tôn đạo tràng"],"nguon":["@c0771"]},{"id":"son-mon-chi-ton-dao-trang","name":"Sơn môn Chí Tôn đạo tràng","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn môn nơi Thạch Hạo tu hành và tiếp đón những người bạn cũ.","detail":"Thạch Hạo trở về đây, mở vườn thuốc và tụ hội cùng Khổng Cầu Kỷ, Tào Vũ Sinh, Thái Âm Ngọc Thỏ. Khu vực quanh sơn môn bị hàng trăm luồng thần niệm theo dõi.","theLucLienQuan":["Chí Tôn đạo tràng"],"nguon":["@c0772"]},{"id":"thu-vien-thien-tien-dia-danh","name":"Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thanh Y tu học và là điểm đến của Thạch Hạo ở cuối chương.","detail":"Truyền nhân Tiên điện và Nguyệt Thiền xuất hiện quanh sự việc liên quan tới Thanh Y. Khi biết nàng có thể bị chặn lại bên trong, Thạch Hạo lập tức lên đường tới đây.","theLucLienQuan":["Thư viện Thiên Tiên","Tiên điện","Bổ Thiên giáo"],"nguon":["@c0772"]},{"id":"dao-tho-cua-nguyet-thien-va-cac-nu-sinh","name":"Đạo thổ của Nguyệt Thiền và các nữ sinh","cn":"","capDo":"khac","parentId":"thu-vien-thien-tien-dia-danh","blurb":"Khu vực nằm sâu trong Thư viện Thiên Tiên, có núi đẹp và hồ nước sáng như bảo thạch. Đây là nơi truyền nhân Tiên điện cùng Nguyệt Thiền tới yêu cầu đưa Thanh Y đi.","detail":"Cuộc tranh chấp về thân phận của Thanh Y diễn ra tại đạo thổ này. Ông lão của thư viện và Phượng Vũ đứng ra bảo vệ nàng, sau đó Thạch Hạo xuất hiện và công khai đối đầu với truyền nhân Tiên điện.","theLucLienQuan":["Thư viện Thiên Tiên","Tiên điện","Bổ Thiên giáo","Đạo tràng Chí tôn"],"nguon":["@c0773"]},{"id":"san-dien-vo-thu-vien-thien-tien","name":"Sân diễn võ Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"thu-vien-thien-tien-dia-danh","blurb":"Võ đài kiên cố trong Thư viện Thiên Tiên, được Thạch Hạo và truyền nhân Tiên điện chọn làm nơi phân thắng bại sống còn.","detail":"Sau khi bị cấm giao chiến tại khu tĩnh tu của nữ đệ tử, Thạch Hạo và truyền nhân Tiên điện chuyển tới sân diễn võ. Học sinh của thư viện, khách các tộc và đông đảo tu sĩ từ bên ngoài kéo đến quanh sân để theo dõi cuộc quyết đấu.","theLucLienQuan":["Thư viện Thiên Tiên","Tiên điện","Cung điện Chí tôn"],"nguon":["@c0774"]},{"id":"vo-dai-thu-vien-thien-tien","name":"Võ đài Thư viện Thiên Tiên","cn":"","capDo":"khac","parentId":"thu-vien-thien-tien-dia-danh","blurb":"Võ đài rộng lớn và kiên cố thuộc Thư viện Thiên Tiên, nơi Thạch Hạo quyết đấu với thứ thân truyền nhân Tiên điện.","detail":"Võ đài chịu lực phá hoại từ cuộc giao chiến bằng lôi đình, bảo thuật và binh khí giữa hai thiên tài.","theLucLienQuan":["Thư viện Thiên Tiên"],"nguon":["@c0775"]},{"id":"tien-quang-hoa-chau","name":"Tiên quáng Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Mỏ quặng cổ nằm sâu trong sa mạc Hỏa châu, hiếm khi có cơ hội tiến vào.","detail":"Sau sáu ngày chờ đợi, mặt cát nứt ra và một ngọn núi phủ sương mù hỗn độn bay lên từ lòng đất. Động cổ trên núi phun khí lành, tiên vụ và phát ra tiếng nổ mang âm hưởng đại đạo.","theLucLienQuan":["Chí Tôn đạo tràng"],"nguon":["@c0777"]},{"id":"dong-phu-hon-nguyen-thach","name":"Động phủ Hỗn Nguyên thạch","cn":"","capDo":"khac","parentId":"tien-quang-hoa-chau","blurb":"Động phủ nhân tạo nằm trong tiên quáng Hỏa châu, được tạo từ một mảnh Hỗn Nguyên thạch khổng lồ.","detail":"Không gian bên trong giống một cung điện và mang khí tức thần thánh. Trên vách có ít nhất năm sáu dấu kiếm, búa và rìu chứa thần vận đại đạo do những cao thủ cái thế để lại.","theLucLienQuan":[],"nguon":["@c0777"]},{"id":"sa-mac-sau-trong-hoa-chau","name":"Sa mạc sâu trong Hỏa châu","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Vùng sa mạc không có cây cỏ nằm sâu trong Hỏa châu.","detail":"Thạch Hạo và Tề Đạo Lâm chờ tại đây sáu ngày trước khi mặt cát nứt ra và tiên quáng trồi lên khỏi lòng đất.","theLucLienQuan":["Chí Tôn đạo tràng"],"nguon":["@c0777"]},{"id":"di-tich-tien-co-cua-tam-thach-thien-quan","name":"Di tích Tiên cổ của Tam thạch Thiên quân","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một di tích Tiên cổ gắn với sự mất tích của Tam thạch Thiên quân.","detail":"Theo lời truyền lại, Tam thạch Thiên quân bất ngờ mất tích khi tiến vào thăm dò di tích này.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0777"]},{"id":"tien-quang","name":"Tiên quáng","cn":"","capDo":"khac","parentId":"hoa-chau","blurb":"Mỏ cổ từ thời Tiên cổ, ẩn trong một ngọn núi có thể di chuyển và chìm xuống lòng đất.","detail":"Vách mỏ lưu giữ vết búa, rãnh kiếm và nhiều đồ án mang áo nghĩa đại đạo. Cơ hội tiến vào chỉ kéo dài trong thời gian ngắn; sau khi chìm xuống đất, nơi này phải qua hàng nghìn hoặc hàng vạn năm mới có thể xuất hiện trở lại.","theLucLienQuan":[],"nguon":["@c0778"]},{"id":"bao-dien-trong-tien-quang","name":"Bảo điện trong Tiên quáng","cn":"","capDo":"khac","parentId":"tien-quang","blurb":"Cổ điện thần thánh nằm sâu trong Tiên quáng, từng thờ và lưu giữ nhiều loại tiên liệu vô thượng.","detail":"Phần lớn tiên liệu trong điện đã bị lấy đi từ thời Tiên cổ, chỉ còn quang ảnh không thể thu giữ. Nơi đây vẫn có một số bảo liệu bị phong ấn cùng các đồ án cổ chứa chân nghĩa đại đạo.","theLucLienQuan":[],"nguon":["@c0778"]},{"id":"ma-chau","name":"Ma châu","cn":"","capDo":"chau","parentId":null,"blurb":"Đại châu nổi tiếng vì ma họa, tội ác và chiến tranh.","detail":"Thạch Hạo tới vùng núi lửa hoang vu tại Ma châu để thăm Thập Ngũ gia trước đại chiến ba ngàn châu, đồng thời tránh các đại giáo thù địch.","theLucLienQuan":["Ma Quỳ viên"],"nguon":["@c0779"]},{"id":"ngu-hanh-chau","name":"Ngũ Hành châu","cn":"","capDo":"chau","parentId":null,"blurb":"Đại châu nơi Thạch Hạo hội ngộ các đồng bạn.","detail":"Đả Thần Thạch và Hoàng điệp chờ Thạch Hạo quay lại tại nơi này.","theLucLienQuan":[],"nguon":["@c0779"]},{"id":"tang-thanh","name":"Tang thành","cn":"","capDo":"thanh","parentId":"toi-chau","blurb":"Một thành đá mang phong mạo nguyên thủy tại Tội châu, là điểm đầu tiên Thạch Hạo dừng chân để thu thập tin tức.","detail":"Tang thành có linh khí mỏng manh, kiến trúc chủ yếu bằng đá nâu xám và một tế đàn truyền tống cực lớn. Nhiều tu sĩ ngoại châu tập trung tại đây trước cuộc tranh đoạt tư cách tiến vào Tiên cổ.","theLucLienQuan":[],"nguon":["@c0780"]},{"id":"phe-tich-thu-phu-thach-quoc","name":"Phế tích thủ phủ Thạch Quốc","cn":"","aliases":["Phế tích cổ quốc Thạch tộc","Di tích Thạch quốc"],"capDo":"khac","parentId":"toi-chau","blurb":"Di tích hoang vu từng là thủ phủ của Thạch Quốc cổ xưa, nơi Thạch Hạo tìm thấy những hậu duệ Thạch tộc đã suy thành phàm nhân.","detail":"Khu phế tích không còn cây cỏ, chỉ có gạch vụn và những bức tường đổ nát. Tại vùng rìa vẫn còn các làng và trại đá lụn bại của hậu duệ Thạch Quốc.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0780"]},{"id":"trai-da-cua-di-dan-thach-toc","name":"Trại đá của di dân Thạch tộc","cn":"","capDo":"khac","parentId":"toi-chau","blurb":"Khu cư trú hoang vu của những hậu duệ Thạch tộc còn sót lại tại Tội châu.","detail":"Trại chỉ có khoảng một hai trăm người mặc da thú cũ nát, không còn dáng vẻ của hậu duệ một quốc gia cổ xưa. Thạch Hạo tới đây hỏi về tội huyết, để lại bảo vật rồi lên đường đến phế tích cổ quốc.","theLucLienQuan":["Thạch tộc thượng giới"],"nguon":["@c0781"]},{"id":"bien-hoang","name":"Biên hoang","cn":"","capDo":"vuc","parentId":null,"blurb":"Tiền tuyến xa xôi nơi tổ tiên của những người mang tội huyết được cho là vẫn đang chiến đấu.","detail":"Tiếng nói truyền qua huyết mạch Thạch Hạo khẳng định các tổ tiên đã tự cắt đường lui, dùng máu xương trấn thủ biên hoang và tiếp tục cuộc huyết chiến.","theLucLienQuan":["Ba mươi tội tộc","Thạch tộc thượng giới"],"nguon":["@c0781"]},{"id":"hoa-thanh","name":"Hỏa thành","cn":"","capDo":"thanh","parentId":"toi-chau","blurb":"Hoàng đô phồn hoa của Hỏa quốc tại Tội châu.","detail":"Thành trì được xây bằng Hỏa Tinh thạch nên từ xa trông như một vùng ánh sáng đỏ lay động. Nhiều chủng tộc cư trú tại đây, còn thiên tài và sơ đại từ các châu đang tập trung trong thành để chờ một cường giả trẻ tuổi thần bí.","theLucLienQuan":["Hỏa quốc","Hỏa tộc"],"nguon":["@c0782"]},{"id":"muoi-cay-hoa-phuong","name":"Mười cây Hỏa Phượng","cn":"","capDo":"khac","parentId":"hoa-thanh","blurb":"Mười cổ thụ nổi bật trong hoàng đô Hỏa quốc.","detail":"Mười cây cổ thụ cao vút đứng song song trong Hỏa thành, cùng tỏa ánh sáng đỏ và bốc lên ngọn lửa.","theLucLienQuan":["Hỏa quốc","Hỏa tộc"],"nguon":["@c0782"]},{"id":"vuon-thuoc-hoa-toc","name":"Vườn thuốc Hỏa tộc","cn":"","capDo":"khac","parentId":"trang-vien","blurb":"Vườn thuốc được đại trận bảo vệ trong trang viên ngoài Hỏa thành.","detail":"Nơi đây lưu giữ hơn mười cây Thánh dược được cho là mang từ hạ giới lên. Nguồn gốc của chúng cung cấp cho Thạch Hạo manh mối đầu tiên về Hỏa Hoàng và Hỏa Linh Nhi.","theLucLienQuan":["Hỏa tộc","Hỏa quốc"],"nguon":["@c0782"]},{"id":"vuon-thuoc-dat-nam-mau","name":"Vườn thuốc đất năm màu","cn":"","capDo":"khac","parentId":null,"blurb":"Vườn thuốc rộng lớn sử dụng đất năm màu phát sáng để nuôi dưỡng nhiều dược thảo. Hơn mười linh dược từ hạ giới đã sống sót và lột xác thành Thánh dược tại đây.","detail":"Đất năm màu trong vườn tỏa ánh sáng và nuôi dưỡng các cây thuốc quý. Phần lớn linh dược hạ giới không chịu nổi áp lực đạo tắc đã chết héo, chỉ hơn mười cây vượt qua và hoàn thành bước lột xác.","theLucLienQuan":["Hỏa quốc"],"nguon":["@c0783"]},{"id":"suon-nui-mai-tang-hong-nhan-cua-truong-cung-dien","name":"Sườn núi mai táng hồng nhan của Trường Cung Diễn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi mai táng người tri kỷ đã mất của Trường Cung Diễn. Đây cũng là địa điểm hai người gặp nhau lần đầu vào một đêm trăng tròn.","detail":"Trường Cung Diễn trở lại sườn núi để tế người tri kỷ. Tiếng khóc của chàng tại đây khiến nhiều Tôn Giả run rẩy, không thể tới gần.","theLucLienQuan":["Ma Văn tộc"],"nguon":["@c0783"]},{"id":"khe-nut-hu-khong","name":"Khe nứt hư không","cn":"","capDo":"khac","parentId":null,"blurb":"Khe nứt hình thành sau lần giao phong giữa Trường Cung Diễn và Cô Kiếm Vân. Hai người tiến vào đó để tìm một chiến trường khác.","detail":"Va chạm giữa kiếm mang và một chỉ khiến hư không xuất hiện nhiều vết nứt. Trường Cung Diễn cùng Cô Kiếm Vân sau đó rời khỏi chiến trường ban đầu qua khe nứt này.","theLucLienQuan":["Kiếm Cốc"],"nguon":["@c0783"]},{"id":"kiem-chau","name":"Kiếm châu","cn":"","capDo":"chau","parentId":"ba-ngan-chau","blurb":"Châu vực nơi Kiếm Cốc được tôn là đệ nhất giáo.","detail":"Kiếm châu là địa bàn của Kiếm Cốc, một đạo thống được xếp vào hàng cao cấp nhất trong phạm vi ba ngàn châu.","theLucLienQuan":["Kiếm Cốc"],"nguon":["@c0784"]},{"id":"thanh-chau","name":"Thanh châu","cn":"","capDo":"chau","parentId":null,"blurb":"Một châu trên đường Tử Viêm Phi tiến tới Tội châu. Tại đây, bốn truyền nhân hàng đầu của một đạo thống cổ cùng tiến đánh hắn nhưng đều bị đánh nổ tung.","detail":"Thanh châu là một trong các địa điểm ghi dấu chuỗi khiêu chiến của Tử Viêm Phi sau khi phá xích thần xuất thế.","theLucLienQuan":[],"nguon":["@c0785"]},{"id":"minh-chau","name":"Minh châu","cn":"","capDo":"chau","parentId":null,"blurb":"Khu vực có một vị sơ đại giao chiến với Tử Viêm Phi. Người này bị hắn chém chết rồi thiêu thành tro.","detail":"Minh châu nằm trên hành trình Tử Viêm Phi vượt nhiều châu để tìm kiếm và thách đấu các cường giả trẻ tuổi.","theLucLienQuan":[],"nguon":["@c0785"]},{"id":"ngon-nui-mau-tim","name":"Ngọn núi màu tím","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Tử Viêm Phi bị xích thần kiềm chế trước khi xuất thế. Hắn kéo đứt xiềng xích tại đây rồi bỏ ngoài tai lời can ngăn của lão bộc.","detail":"Ngọn núi màu tím là điểm khởi đầu cho hành trình Tử Viêm Phi vượt qua nhiều châu để tìm đối thủ.","theLucLienQuan":[],"nguon":["@c0785"]},{"id":"day-nui-nguyen-thuy","name":"Dãy núi nguyên thủy","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Thạch Hạo ẩn mình sau khi rời Hỏa thành. Hắn chờ mưa giông bao phủ để dẫn thiên kiếp, rèn nguyên thần và thể xác trước khi xung kích Tôn Giả cảnh đại viên mãn.","detail":"Dãy núi có thời tiết dữ dội và vùng sấm sét thích hợp cho kế hoạch vận dụng Bảo thuật Lôi Đế của Thạch Hạo.","theLucLienQuan":[],"nguon":["@c0785"]},{"id":"tang-may-thien-kiep","name":"Tầng mây thiên kiếp","cn":"","capDo":"khac","parentId":"day-nui-do-kiep","blurb":"Tầng mây đen chứa lôi đình dày đặc, nơi Thạch Hạo trực tiếp đón thiên kiếp để rèn luyện.","detail":"Thiên uy tại đây tác động đồng thời lên thân thể và tinh thần. Thạch Hạo tiến vào biển sét, luyện thân và nguyên thần, đồng thời gặp những sinh linh kỳ dị ẩn trong tia chớp.","theLucLienQuan":[],"nguon":["@c0786"]},{"id":"day-nui-do-kiep","name":"Dãy núi độ kiếp","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng núi yên tĩnh bị mây đen và giông tố bao phủ, được Thạch Hạo chọn làm nơi chuẩn bị đón thiên kiếp.","detail":"Khí tức yêu dị của cơn giông khiến chim thú trong vùng đều trốn tránh. Thạch Hạo điều chỉnh tinh khí thần trên một ngọn núi tại đây rồi bay lên tầng mây để tìm Lôi Kiếp dịch và dùng lôi đình luyện thể.","theLucLienQuan":[],"nguon":["@c0786"]},{"id":"dinh-loi-dinh","name":"Đỉnh lôi đình","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Chiếc đỉnh được cấu thành hoàn toàn từ lôi đình trong trận thiên kiếp của Thạch Hạo.","detail":"Đỉnh dẫn dắt sấm sét để rèn luyện Thạch Hạo, đồng thời là nơi hắn khống chế và luyện hóa sạch sinh linh lôi đình không có linh hồn.","theLucLienQuan":[],"nguon":["@c0787"]},{"id":"suon-doc-loi-dinh","name":"Sườn dốc lôi đình","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Địa hình lôi đình xuất hiện sau khi những thác nước sấm sét khô cạn.","detail":"Thạch Hạo ngồi trên sườn dốc này vận chuyển cốt văn, ổn định thân thể và nguyên thần sau khi hấp thu sinh cơ từ lôi đình.","theLucLienQuan":[],"nguon":["@c0787"]},{"id":"day-nui-loi-dinh","name":"Dãy núi lôi đình","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Dãy núi do sấm sét biến thành trong tầng thiên kiếp thứ mười.","detail":"Đây là chiến trường nơi Thạch Hạo đối đầu người cưỡi chiến mã cầm phương thiên họa kích. Dãy núi dần mất ổn định và tan biến khi thiên kiếp rút đi.","theLucLienQuan":[],"nguon":["@c0787"]},{"id":"ao-chop-trong-tang-may","name":"Ao chớp trong tầng mây","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Khu vực ao chớp nằm sâu giữa tầng mây và ánh lôi đình sau khi thiên kiếp kết thúc.","detail":"Nơi đây chứa ao lôi dịch cổ xưa với chất lỏng đậm đặc, óng ánh và thơm ngào ngạt, được Thạch Hạo phát hiện ngay sau khi vượt qua tầng kiếp thứ mười.","theLucLienQuan":[],"nguon":["@c0787"]},{"id":"loi-tri","name":"Lôi trì","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Một ao đá cổ nằm trong tầng mây sấm sét, rộng khoảng hai thước vuông và chứa Lôi kiếp dịch màu tím.","detail":"Vách ao mang dấu vết cổ xưa, nhưng Thạch Hạo không xác định được đây là vật chân thực hay hình thể do tia chớp biến hóa. Sau khi hắn hấp thu gần một nửa thần dịch và rời đi, toàn bộ vị trí của Lôi trì bị sấm sét nhấn chìm.","theLucLienQuan":[],"nguon":["@c0788"]},{"id":"loi-dao-thien-khung","name":"Lôi đạo Thiên khung","cn":"","capDo":"khac","parentId":"tang-may-thien-kiep","blurb":"Tầng trời được tạo thành từ ánh chớp, gồm tầng thiên kiếp Thạch Hạo vừa vượt qua và một tầng kiếp Thần linh cao hơn.","detail":"Tầng phía trên vượt quá cảnh giới hiện tại của Thạch Hạo và ẩn chứa hung hiểm có thể thiêu hắn thành than. Hắn dự định chỉ quay lại sau khi nhen nhóm Thần Hỏa và đạt tới trạng thái Đại viên mãn.","theLucLienQuan":[],"nguon":["@c0788"]},{"id":"ao-mau-vang-sau-kiep-than-linh","name":"Ao màu vàng sau kiếp Thần linh","cn":"","capDo":"khac","parentId":"loi-dao-thien-khung","blurb":"Một ao thần bí thấp thoáng phía sau màn sét của tầng kiếp Thần linh.","detail":"Ao chứa chất lỏng màu vàng khác với Lôi kiếp dịch màu tím. Quanh đó còn hiện ra các cảnh tượng cổ thụ, phòng ốc, Kim Ô và rồng, nhưng Thạch Hạo chưa thể tiếp cận ở cảnh giới hiện tại.","theLucLienQuan":[],"nguon":["@c0788"]},{"id":"thanh-ly-hoa","name":"Thành Ly Hỏa","cn":"","capDo":"thanh","parentId":"hoa-quoc","blurb":"Thành trì của Hỏa tộc, nơi Thạch Hạo gặp lại Hỏa Linh Nhi trước khi đại quyết chiến thiên tài ba ngàn châu mở màn.","detail":"Thành Ly Hỏa nằm giữa khu vực có nhiều rừng dâu lửa và tằm lửa. Hỏa Linh Nhi sống giản dị tại đây, còn Thạch Hạo lần theo manh mối từ Hoàng đô Hỏa quốc để tìm đến gặp nàng.","theLucLienQuan":["Hỏa tộc"],"nguon":["@c0789"]},{"id":"rung-dau-lua","name":"Rừng dâu lửa","cn":"","capDo":"khac","parentId":"thanh-ly-hoa","blurb":"Khu rừng quanh thành Ly Hỏa có những cây dâu phun lửa và tằm lửa ăn lá.","detail":"Hỏa Linh Nhi hái lá dâu nuôi tằm và sống trong một căn nhà tranh tại đây. Trong rừng phía sau nhà còn có ngôi mộ không bia chôn chiến y của Thạch Hạo.","theLucLienQuan":["Hỏa tộc"],"nguon":["@c0789"]},{"id":"son-mon-con-mon","name":"Sơn môn Côn môn","cn":"","capDo":"khac","parentId":"toi-chau","blurb":"Sơn môn hoang vắng của Côn môn nằm trên một ngọn núi lớn tại Tội châu.","detail":"Nơi đây có bậc đá xanh bị giẫm lõm, nhiều điện cổ nứt vỡ và chỉ còn hai thầy trò sinh sống. Dù hoang phế, địa thế sông núi vẫn được Thạch Hạo nhận xét là bất phàm.","theLucLienQuan":["Côn môn"],"nguon":["@c0791"]},{"id":"dao-truong-tuyen-chon-toi-chau","name":"Đạo trường tuyển chọn Tội châu","cn":"","capDo":"khac","parentId":"toi-chau","blurb":"Đạo trường cổ dùng để tập hợp tám triệu Tôn giả tham gia vòng tuyển chọn tại Tội châu.","detail":"Không gian đạo trường rộng đến mức tám triệu người đứng bên trong vẫn còn cách xa nhau. Phù văn và đại trận bao phủ nơi này để tổ chức tuyển chọn và ngăn thế lực bên ngoài can thiệp.","theLucLienQuan":[],"nguon":["@c0791"]},{"id":"day-nui-tuyet-noi-quan-dao-ngu-say","name":"Dãy núi tuyết nơi Quân Đạo ngủ say","cn":"","capDo":"khac","parentId":null,"blurb":"Dãy núi tuyết liên miên tại thượng giới, nơi Quân Đạo ngủ trong một kẽ băng qua nhiều năm.","detail":"Quân Đạo thức tỉnh tại đây trước khi hướng tới vận may Tiên cổ.","theLucLienQuan":[],"nguon":["@c0791"]},{"id":"chau-lon-nui-lua","name":"Châu lớn núi lửa","cn":"","capDo":"chau","parentId":null,"blurb":"Một châu cổ có nhiều núi lửa và dung nham, nơi quan tài Sinh mệnh của cô gái tóc đỏ xuất hiện.","detail":"Quan tài cổ màu đỏ đậm nằm giữa dung nham tại châu này và mở ra khi cô gái tóc đỏ thức tỉnh lần cuối.","theLucLienQuan":[],"nguon":["@c0791"]},{"id":"long-cung-bang-thuy-tinh","name":"Long cung bằng thủy tinh","cn":"","capDo":"khac","parentId":null,"blurb":"Cung điện bằng thủy tinh nằm dưới một vùng biển lớn, nơi cô gái có sừng rồng ngủ say.","detail":"Cô gái có sừng rồng mở mắt trong Long cung, tạo ra chùm sáng xuyên lên mây rồi bay từ đáy biển lên trời.","theLucLienQuan":[],"nguon":["@c0791"]},{"id":"chien-truong-dam-lay","name":"Chiến trường đầm lầy","cn":"","capDo":"khac","parentId":"tam-muoi-chien-truong-linh-gioi","blurb":"Một chiến trường đầm lầy âm u thuộc vòng tuyển chọn tại Linh giới.","detail":"Nơi này có cổ thụ thưa thớt và khoảng mười vạn Tôn giả tham gia hỗn chiến. Thạch Hạo giết những người tập kích rồi vượt khỏi khu vực sau hơn hai canh giờ.","theLucLienQuan":[],"nguon":["@c0793"]},{"id":"tam-muoi-chien-truong-linh-gioi","name":"Tám mươi chiến trường Linh giới","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Hệ thống tám mươi chiến trường tiếp giáp nhau trong vòng tuyển chọn Tiên cổ.","detail":"Các chiến trường ban đầu chứa tổng cộng tám triệu Tôn giả và cộng hưởng ý chí cùng sát niệm của người dự thi. Sau hơn hai canh giờ hỗn chiến, hơn bảy triệu người đã thất bại.","theLucLienQuan":[],"nguon":["@c0793"]},{"id":"dan-co-chi-ton","name":"Đàn cổ Chí tôn","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Cửa ải cuối của vòng tuyển chọn tại Linh giới, mang hình dạng một tế đàn đen khổng lồ.","detail":"Đàn cổ cao vút trong mây, trên đỉnh đặt một chiếc bát chứa Chí tôn dịch. Những người sống sót từ các chiến trường được triệu tập tới đây để quyết định tư cách tiến vào Tiên cổ.","theLucLienQuan":["Đạo phái Yêu Long","Động Hỏa Vân"],"nguon":["@c0793"]},{"id":"dao-trang-lon-ngoai-toi-chau","name":"Đạo tràng lớn ngoài Tội châu","cn":"","capDo":"khac","parentId":"toi-chau","blurb":"Đạo tràng nơi thân thể thật của người dự thi vòng tuyển chọn ngồi xếp bằng.","detail":"Những người chết hoặc bị loại trong Linh giới tỉnh lại tại đây. Sau vòng hỗn chiến, đại trận cấm kỵ chuyển hơn bảy triệu người thất bại khỏi khu vực đạo tràng.","theLucLienQuan":[],"nguon":["@c0793"]},{"id":"tam-con-duong-vao-dan-co-chi-ton","name":"Tám con đường vào đàn cổ Chí tôn","cn":"","capDo":"khac","parentId":"dan-co-chi-ton","blurb":"Tám lối tiến vào đàn cổ Chí tôn, đều bị các đạo thống hoặc thuộc hạ Ninh Xuyên bố trí người canh giữ.","detail":"Những kẻ canh đường vừa chèn ép các tu sĩ Tội châu vừa dùng gương báu tìm người có chữ Tội phá mây. Thạch Hạo khảo sát cả tám lối trước khi quyết định ra tay giết trả.","theLucLienQuan":["Hỏa Vân động","Yêu Long đạo môn","La Phù chân cốc"],"nguon":["@c0794"]},{"id":"tang-thu-ba-dan-co-chi-ton","name":"Tầng thứ ba của đàn cổ Chí tôn","cn":"","capDo":"khac","parentId":"dan-co-chi-ton","blurb":"Tầng thứ ba là nơi tám con đường tiến vào đàn cổ Chí tôn hợp thành một.","detail":"Thạch Hạo chọn vị trí hợp nhất của tám con đường làm nơi giữ ải. Tại đây, hắn ngăn người thuộc các đạo thống áp chế Tội châu tiếp tục tiến lên và đánh tan đội ngũ hơn trăm người.","theLucLienQuan":["Các đạo thống trông nom Tội châu"],"nguon":["@c0796"]},{"id":"tang-thu-tu-dan-co-chi-ton","name":"Tầng thứ tư của đàn cổ Chí tôn","cn":"","capDo":"khac","parentId":"dan-co-chi-ton","blurb":"Tầng thứ tư nằm phía trên vị trí Thạch Hạo giữ ải tại tầng ba.","detail":"Sáu người áo trắng của Lục Quan Vương đang tiến lên tầng thứ tư trước khi quay xuống tầng ba, mang theo sáu hộp báu để đối phó Thạch Hạo.","theLucLienQuan":[],"nguon":["@c0796"]},{"id":"khu-vuc-tuyen-chon-bi-ap-che-canh-gioi","name":"Khu vực tuyển chọn bị áp chế cảnh giới","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực giao chiến trong cuộc tuyển chọn, nơi cảnh giới và sức mạnh của người tham dự đều bị áp chế.","detail":"Tại đây, Chân Thần và Thiên Thần chỉ có thể phát huy sức mạnh ở Tôn giả cảnh, còn uy lực pháp khí mang vào cũng chịu hạn chế. Điều kiện này cho phép Thạch Hạo giao chiến trực diện với đông đảo cường giả có cảnh giới thật cao hơn mình.","theLucLienQuan":["Hóa Vân động","Hỏa Vân động","Yêu Long Đạo môn","La Phù Chân cốc"],"nguon":["@c0799"]},{"id":"khu-vuc-rong-lon-khong-nguoi","name":"Khu vực rộng lớn không người","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm đến của một vạn Tôn giả vượt qua cuộc kiểm tra tại Tội châu.","detail":"Sau khi tiếng chuông vang lên và đại trận vận chuyển, một vạn Tôn giả thắng cuộc bắt đầu được truyền tống tới khu vực rộng lớn không người này.","theLucLienQuan":[],"nguon":["@c0800"]}]};
